import { tv, type VariantProps } from "@/lib/beton/tv";

export const statsBand = tv({
  slots: {
    list: "grid divide-border border-3 border-border bg-raised",
    item: "flex flex-col gap-1 p-6",
    value: "font-display font-black tabular-nums text-foreground",
    label: "font-mono text-xs font-bold tracking-widest uppercase",
    description: "text-sm text-foreground",
  },
  variants: {
    columns: {
      2: { list: "sm:grid-cols-2 sm:divide-x-3 divide-y-3 sm:divide-y-0" },
      3: { list: "sm:grid-cols-3 sm:divide-x-3 divide-y-3 sm:divide-y-0" },
      4: { list: "sm:grid-cols-2 lg:grid-cols-4 divide-y-3 sm:divide-y-0 sm:divide-x-3" },
    },
    size: {
      sm: { value: "text-h3" },
      md: { value: "text-h2" },
      lg: { value: "text-h1" },
    },
  },
  defaultVariants: {
    columns: 4,
    size: "md",
  },
});

export type StatsBandVariants = VariantProps<typeof statsBand>;

import { statsBand, type StatsBandVariants } from "@/lib/beton/recipes/stats-band.recipe";
import type { ReactNode } from "react";
import { Section, type SectionProps } from "@/components/ui/beton/section";

export interface BandStat {
  /** The number, already formatted, or a Counter. */
  value: ReactNode;
  /** What the number measures. */
  label: ReactNode;
  /** A line of context under it. */
  description?: ReactNode;
}

export interface StatsBandProps extends Omit<SectionProps, "children">, StatsBandVariants {
  /** The numbers, in order. */
  stats: BandStat[];
  /** Classes for the strip itself. */
  listClassName?: string;
}

/** A strip of numbers that say how much, how many, how fast. */
export function StatsBand({
  stats,
  columns = 4,
  size = "md",
  listClassName,
  ...props
}: StatsBandProps) {
  const styles = statsBand({ columns, size });
  return (
    <Section {...props}>
      <dl className={styles.list({ class: listClassName })}>
        {stats.map((stat, index) => (
          <div key={index} className={styles.item()}>
            <dt className={styles.label()}>{stat.label}</dt>
            <dd className={styles.value()}>{stat.value}</dd>
            {stat.description ? <dd className={styles.description()}>{stat.description}</dd> : null}
          </div>
        ))}
      </dl>
    </Section>
  );
}
